options.customCss:
div.html em { font-style: normal; color: #7e8186; font-size: 12px; }
div.html ol { margin-top: 8px; }
div.html li { margin-bottom: 4px; }
div.html h4 { margin-top: 24px; font-weight: 600; }
div.html li:has(> i) { color: #7e8186; }
div.html li > i { font-style: normal; color: #7e8186; }
div.html strong { color: #b00020; font-weight: 600; }

